-- Academy: rebuild Yachts Module 7 as "Think Like a Broker": 21 pages (9 with quick checks, 12 with answerable exercises
-- saved to the Broker Portfolio) + a 7-question final quiz. Same shape as the Module 1 migration.

do $mig$
declare
  v_module uuid;
  v_q uuid;
  v_page uuid;
  rec jsonb;
  n int := 0;
  i int;
  v_pages jsonb := $json$[{"heading": "Think Like a Broker", "body": "<p><b>Can I actually do this?</b></p><p>You have learned what yachts are. You have explored the market. You have learned how clients think. You have seen how brokerages operate. You have followed a transaction from first interest through closing.</p><p>Now comes the important shift. You stop asking: <em>\"What does a broker know?\"</em> And start asking: <b>\"What would I do if I were the broker?\"</b> That is a very different question.</p><p>A broker rarely has perfect information. You may have:</p><p>&bull; an enthusiastic client<br/>&bull; five possible yachts<br/>&bull; incomplete specifications<br/>&bull; conflicting information<br/>&bull; a limited budget<br/>&bull; a seller with a strong position<br/>&bull; a yacht that looks attractive but raises questions<br/>&bull; and a decision that needs to be made today</p><p>The broker's job is not to know everything. It is to <b>think clearly when the information is incomplete.</b> This module is about developing that judgment.</p>", "q": "What is the broker's job when information is incomplete?", "opts": ["To know everything before advising", "To think clearly and exercise judgment despite the gaps", "To wait until every fact is confirmed", "To choose the most attractive yacht"], "correct": 1}, {"heading": "Chapter 1: Develop the Broker's Eye", "body": "<p><b>Seeing beyond the yacht</b></p><p>Two people can walk onto the same yacht and see completely different things. A first-time visitor might see: <em>beautiful interior, large master cabin, great swimming platform.</em> A broker asks: <b>who is this yacht actually suited to?</b> Then: what compromises does it make? Then: how does it compare with the alternatives? That is the beginning of the broker's eye.</p><p><b>The broker's seven questions</b></p><p>Whenever you encounter a yacht, train yourself to ask:</p><p>&bull; <b>1. What is it?</b> What type of yacht is it?<br/>&bull; <b>2. What was it designed to do?</b> Family cruising, long-range exploration, entertaining, charter, performance sailing?<br/>&bull; <b>3. Who is it for?</b> What type of owner would genuinely enjoy it?<br/>&bull; <b>4. What does it do particularly well?</b> Its strengths.<br/>&bull; <b>5. Where does it compromise?</b> Its limitations.<br/>&bull; <b>6. What is unknown?</b> What needs to be verified?<br/>&bull; <b>7. Compared with what?</b> No yacht exists in isolation. A yacht only becomes commercially meaningful when you understand its alternatives.</p><p><b>Strengths are not universal</b></p><p>Imagine a yacht has a very large exterior deck. That may be a major advantage for entertaining, family lunches, outdoor living and water sports. But it may matter less to a client who spends most of their time cruising in cooler climates and prioritises interior volume. A very fast yacht may be attractive to one client and completely unnecessary to another. A huge master suite may impress one buyer but mean less than crew accommodation to someone planning extensive family cruising.</p><p>There is no universal definition of \"best\". There is only: <b>best fit for a particular purpose and client.</b></p>", "q": "Why is there no universal \"best\" yacht?", "opts": ["Because all yachts are equivalent", "Because price decides everything", "Because only the market defines quality", "Because each strength matters differently depending on the client and purpose"], "correct": 3}, {"heading": "Exercise: Find the Trade-Off", "body": "<p><b>Try it</b></p><p>Choose any yacht you have encountered in the academy. Write three strengths and three limitations. Then complete: <em>\"This yacht would be particularly suitable for a client who ________.\"</em> And: <em>\"It would be less suitable for a client who ________.\"</em></p><p>You are beginning to move from description to judgment.</p>", "exercise": {"intro": "Pick one yacht and be specific.", "groups": [{"title": "Strengths and limitations", "section": "yachts", "fields": [{"key": "ft_yacht", "label": "The yacht I chose", "type": "short", "min": 4}, {"key": "ft_str", "label": "Three strengths", "type": "long", "min": 40}, {"key": "ft_lim", "label": "Three limitations", "type": "long", "min": 40}, {"key": "ft_suit", "label": "This yacht would be particularly suitable for a client who...", "type": "long", "min": 20}, {"key": "ft_less", "label": "It would be less suitable for a client who...", "type": "long", "min": 20}]}]}}, {"heading": "Chapter 2: The Yacht Shortlist", "body": "<p><b>A shortlist is not a list</b></p><p>A beginner might send a client: <em>\"Here are 17 yachts that match your search.\"</em> That is easy. It is also not particularly useful. The client does not necessarily need more information. They need <b>better information.</b> A professional shortlist might contain three to five serious opportunities. Each should have a reason for being there.</p><p><b>The filtering process</b></p><p>Start broad. Imagine there are 40 yachts that appear to match the basic search. Then filter.</p><p>&bull; <b>Stage 1, basic fit:</b> does the yacht fit the fundamental parameters (size, budget, location, guest requirements, broad purpose)?<br/>&bull; <b>Stage 2, lifestyle fit:</b> does it actually suit the client's way of using a yacht?<br/>&bull; <b>Stage 3, practical fit:</b> does the layout, crew arrangement, range, maintenance position and operating profile make sense?<br/>&bull; <b>Stage 4, market fit:</b> how does it compare with competing yachts?<br/>&bull; <b>Stage 5, risk and unknowns:</b> what needs further investigation?<br/>&bull; <b>Stage 6, shortlist:</b> which opportunities deserve the client's time?</p><p><b>Why fewer can be better</b></p><p>Imagine presenting: <b>Option A,</b> strong overall fit. <b>Option B,</b> excellent family layout, but higher operating complexity. <b>Option C,</b> lower price, but significant questions about condition. That creates a useful conversation. Presenting 20 yachts creates a research project for the client. The broker's value lies partly in reducing unnecessary complexity.</p><p><b>Broker's Insight</b></p><p><b>Your client should not need to become the broker just to understand your shortlist.</b></p>", "q": "Why can a shortlist of three to five yachts be better than 17?", "opts": ["It gives the client better information, each option with a reason for being there, instead of a research project", "It hides the alternatives from the client", "It is faster for the broker to compile", "It guarantees a sale"], "correct": 0}, {"heading": "Exercise: Build a Shortlist", "body": "<p><b>Try it</b></p><p>Use the three yachts from your Module 3 market analysis. For each, assess client fit, lifestyle fit, strength, concern, unknown, market position and why consider it.</p><p>Then identify which two deserve further investigation. More importantly: <b>why did you remove the others?</b></p>", "exercise": {"intro": "Three yachts, seven lenses each.", "groups": [{"title": "Yacht A", "section": "yachts", "fields": [{"key": "sl_a_name", "label": "Yacht A: name or description", "type": "short", "min": 4}, {"key": "sl_a_fit", "label": "Yacht A: Client fit", "type": "long", "min": 10}, {"key": "sl_a_life", "label": "Yacht A: Lifestyle fit", "type": "long", "min": 10}, {"key": "sl_a_str", "label": "Yacht A: Strength", "type": "long", "min": 10}, {"key": "sl_a_con", "label": "Yacht A: Concern", "type": "long", "min": 10}, {"key": "sl_a_unk", "label": "Yacht A: Unknown", "type": "long", "min": 10}, {"key": "sl_a_mkt", "label": "Yacht A: Market position", "type": "long", "min": 10}, {"key": "sl_a_why", "label": "Yacht A: Why consider it?", "type": "long", "min": 10}]}, {"title": "Yacht B", "section": "yachts", "fields": [{"key": "sl_b_name", "label": "Yacht B: name or description", "type": "short", "min": 4}, {"key": "sl_b_fit", "label": "Yacht B: Client fit", "type": "long", "min": 10}, {"key": "sl_b_life", "label": "Yacht B: Lifestyle fit", "type": "long", "min": 10}, {"key": "sl_b_str", "label": "Yacht B: Strength", "type": "long", "min": 10}, {"key": "sl_b_con", "label": "Yacht B: Concern", "type": "long", "min": 10}, {"key": "sl_b_unk", "label": "Yacht B: Unknown", "type": "long", "min": 10}, {"key": "sl_b_mkt", "label": "Yacht B: Market position", "type": "long", "min": 10}, {"key": "sl_b_why", "label": "Yacht B: Why consider it?", "type": "long", "min": 10}]}, {"title": "Yacht C", "section": "yachts", "fields": [{"key": "sl_c_name", "label": "Yacht C: name or description", "type": "short", "min": 4}, {"key": "sl_c_fit", "label": "Yacht C: Client fit", "type": "long", "min": 10}, {"key": "sl_c_life", "label": "Yacht C: Lifestyle fit", "type": "long", "min": 10}, {"key": "sl_c_str", "label": "Yacht C: Strength", "type": "long", "min": 10}, {"key": "sl_c_con", "label": "Yacht C: Concern", "type": "long", "min": 10}, {"key": "sl_c_unk", "label": "Yacht C: Unknown", "type": "long", "min": 10}, {"key": "sl_c_mkt", "label": "Yacht C: Market position", "type": "long", "min": 10}, {"key": "sl_c_why", "label": "Yacht C: Why consider it?", "type": "long", "min": 10}]}, {"title": "The decision", "section": "yachts", "fields": [{"key": "sl_two", "label": "Which two deserve further investigation?", "type": "short", "min": 6}, {"key": "sl_removed", "label": "Why did you remove the other(s)?", "type": "long", "min": 40}]}]}}, {"heading": "Chapter 3: Make the Recommendation", "body": "<p><b>The moment a broker has to take a position</b></p><p>A client asks: <em>\"If this were your decision, which yacht would you look at first?\"</em> This is where many beginners become uncomfortable. They respond: <em>\"They're all very good.\"</em> That may be safe. It is not particularly useful. A broker should be able to explain their reasoning. But there is an important distinction: <b>recommendation is not decision.</b> The broker provides professional judgment. The client makes the decision.</p><p><b>The structure of a strong recommendation</b></p><p>Try this: <em>\"Based on what you've told me, I would prioritise Yacht A because...\"</em> Then explain:</p><p>&bull; <b>1. Client fit:</b> how does it match the client's actual needs?<br/>&bull; <b>2. Strength:</b> what does it do particularly well?<br/>&bull; <b>3. Trade-off:</b> what does the client give up?<br/>&bull; <b>4. Concern:</b> what needs to be investigated?<br/>&bull; <b>5. Comparison:</b> why does it deserve attention relative to the alternatives?<br/>&bull; <b>6. Next step:</b> what should happen before making a decision?</p><p><b>Example</b></p><p><em>\"Based on what you've told me, I would put Yacht A first for viewing. The family layout and exterior spaces seem particularly aligned with how you described using the yacht. The main question for me is the operational and maintenance position, which I'd want to investigate before becoming more enthusiastic about it. Yacht B is also worth seeing because it offers a different ownership proposition, particularly if keeping the operating profile simpler becomes more important.\"</em></p><p>Notice what this does. It does not say <em>\"Yacht A is the best.\"</em> It explains <b>why it deserves attention.</b></p><p><b>Avoid false certainty</b></p><p>A broker should be comfortable saying: <em>\"Based on the information we have...\"</em>, <em>\"My initial view is...\"</em>, <em>\"I would want to verify...\"</em>, <em>\"The main trade-off appears to be...\"</em>, <em>\"I'd like to compare this with...\"</em>, <em>\"I don't think we know enough yet...\"</em> Professional confidence is not pretending to have perfect certainty.</p>", "q": "A client asks which yacht you'd look at first. What is a strong answer?", "opts": ["\"They're all very good.\"", "\"The most expensive one is the best.\"", "Name one, explain why it deserves attention, state the trade-off and concern, and propose a next step", "\"I can't advise on that.\""], "correct": 2}, {"heading": "Exercise: Give Your Recommendation", "body": "<p><b>Try it</b></p><p>Return to your Module 3 yachts. Choose one that you would prioritise <b>for a hypothetical client,</b> not because you personally like it. Write a 150-word recommendation. It must include client fit, one major strength, one trade-off, one concern, one reason it deserves further attention and one next step.</p><p>Then read it aloud. Does it sound like advice? Or does it sound like marketing?</p>", "exercise": {"intro": "About 150 words. Advice, not marketing.", "groups": [{"title": "My recommendation", "section": "services", "fields": [{"key": "gr_client", "label": "The hypothetical client", "type": "short", "min": 10}, {"key": "gr_text", "label": "Your recommendation (about 150 words)", "type": "long", "min": 500}, {"key": "gr_check", "label": "Read it aloud: does it sound like advice or marketing? What would you change?", "type": "long", "min": 30}]}]}}, {"heading": "Chapter 4: Find the Questions", "body": "<p><b>The most valuable thing you can say may be: \"We need to investigate that.\"</b></p><p>Brokerage is full of incomplete information. A listing may tell you length, beam, year, cabins, engines, speed and price. But important questions remain:</p><p>&bull; <b>Ownership:</b> who has owned the yacht? How has it been used?<br/>&bull; <b>Maintenance:</b> what has been done, when, and by whom?<br/>&bull; <b>Machinery:</b> what are the hours? What major work has been completed?<br/>&bull; <b>Condition:</b> what has been surveyed? What remains uncertain?<br/>&bull; <b>Operation:</b> how many crew are normally required?<br/>&bull; <b>Financial:</b> what are the realistic ongoing ownership costs?<br/>&bull; <b>Market:</b> how long has it been for sale? How does it compare with similar yachts?</p><p><b>The Question Ladder</b></p><p>When something matters, go deeper.</p><p>&bull; <b>Level 1, what?</b> <em>\"Has the yacht been refitted?\"</em><br/>&bull; <b>Level 2, when?</b> <em>\"When was the work completed?\"</em><br/>&bull; <b>Level 3, what exactly?</b> <em>\"Which areas were included?\"</em><br/>&bull; <b>Level 4, who?</b> <em>\"Who carried out the work?\"</em><br/>&bull; <b>Level 5, evidence?</b> <em>\"Is there documentation available?\"</em></p><p>This is how a broker moves from a headline to useful information.</p><p><b>Don't interrogate for the sake of it</b></p><p>More questions do not automatically mean better brokerage. Ask: <b>what decision will this information help us make?</b> That question helps you prioritise.</p>", "q": "Which question best helps you prioritise what to investigate?", "opts": ["How many questions can we ask?", "What does the listing already say?", "What would the seller prefer we ask?", "What decision will this information help us make?"], "correct": 3}, {"heading": "Exercise: The Five Questions", "body": "<p><b>Try it</b></p><p>Take one yacht from your shortlist. Write the <b>five questions you would most want answered before recommending a viewing.</b> Then rank them: 1 most important, 2 and 3 important, 4 and 5 useful. Explain why Question 1 matters most.</p>", "exercise": {"intro": "Rank as you write: Q1 is the most important.", "groups": [{"title": "My five questions, ranked", "section": "yachts", "fields": [{"key": "fq_yacht", "label": "The yacht", "type": "short", "min": 4}, {"key": "fq_1", "label": "Question 1 (most important)", "type": "short", "min": 15}, {"key": "fq_2", "label": "Question 2 (important)", "type": "short", "min": 15}, {"key": "fq_3", "label": "Question 3 (important)", "type": "short", "min": 15}, {"key": "fq_4", "label": "Question 4 (useful)", "type": "short", "min": 15}, {"key": "fq_5", "label": "Question 5 (useful)", "type": "short", "min": 15}, {"key": "fq_why", "label": "Why does Question 1 matter most?", "type": "long", "min": 40}]}]}}, {"heading": "Chapter 5: Position the Opportunity", "body": "<p><b>A yacht does not sell itself</b></p><p>A yacht can be technically excellent and still be poorly positioned. Positioning means understanding: <b>why should this particular yacht matter to this particular buyer?</b> Consider a yacht with five cabins, large outdoor spaces, moderate cruising speed, extensive recent maintenance and a relatively traditional interior. You could describe it as: <em>\"A 35m motor yacht with five cabins and large outdoor areas.\"</em> That is accurate. But it does not communicate much. For the right client, you might instead say:</p><p><em>\"A family-oriented 35m yacht with generous outdoor living and a strong recent maintenance position, particularly interesting if relaxed time aboard matters more than high-speed performance or ultra-modern design.\"</em></p><p>That is positioning.</p><p><b>Positioning is not exaggeration</b></p><p>A broker should not turn <em>\"Recently maintained\"</em> into <em>\"Immaculately maintained and mechanically perfect.\"</em> Nor <em>\"Good family layout\"</em> into <em>\"The ultimate family yacht.\"</em> Professional positioning is built from evidence.</p><p><b>The four-part positioning model</b></p><p>&bull; <b>WHO:</b> who is this yacht for?<br/>&bull; <b>WHY:</b> why might they care?<br/>&bull; <b>DIFFERENCE:</b> what distinguishes it?<br/>&bull; <b>TRADE-OFF:</b> what should they understand before becoming emotionally attached?</p><p>This last part is important. A credible recommendation includes the compromise.</p>", "q": "What is professional positioning built from?", "opts": ["Superlatives that make the yacht sound special", "Evidence, presented for a particular buyer, including the trade-off", "Whatever the seller wants emphasised", "The yacht's asking price alone"], "correct": 1}, {"heading": "Exercise: Position the Yacht", "body": "<p><b>Try it</b></p><p>Choose one yacht. Write a one-sentence positioning (<em>\"This yacht is particularly interesting for a client who...\"</em>), three supporting facts, one important trade-off and one question still to investigate.</p>", "exercise": {"intro": "Evidence only. No superlatives.", "groups": [{"title": "Positioning", "section": "yachts", "fields": [{"key": "po_yacht", "label": "The yacht", "type": "short", "min": 4}, {"key": "po_sentence", "label": "\"This yacht is particularly interesting for a client who...\"", "type": "long", "min": 30}, {"key": "po_f1", "label": "Supporting fact 1", "type": "short", "min": 10}, {"key": "po_f2", "label": "Supporting fact 2", "type": "short", "min": 10}, {"key": "po_f3", "label": "Supporting fact 3", "type": "short", "min": 10}, {"key": "po_trade", "label": "One important trade-off", "type": "long", "min": 20}, {"key": "po_q", "label": "One question still to investigate", "type": "short", "min": 15}]}]}}, {"heading": "Chapter 6: The Complete Broker Challenge", "body": "<p><b>You are the broker now</b></p><p>This is your first complete broker exercise. You have <b>45 to 60 minutes.</b> Work from the information provided. Do not invent technical, financial or ownership facts. Where information is missing, identify it as an <b>unknown.</b></p><p><b>The client: Alex and Emma</b></p><p>&bull; first-time yacht buyers<br/>&bull; budget: approximately €8m<br/>&bull; Mediterranean use, four to six weeks aboard each summer<br/>&bull; two children, regular family guests<br/>&bull; prefer relaxed outdoor living and want good privacy<br/>&bull; do not want an excessively complicated ownership experience<br/>&bull; interested in approximately 35m<br/>&bull; have seen several yachts online; excited but with very little technical knowledge</p><p>They tell you: <em>\"We don't really know what we're looking for yet. We just know we want something special.\"</em></p><p><b>Yacht A</b></p><p>35.2m, 2016, <b>€8.80m asking</b>, 5 cabins, 10 guests, 245 GT, 12-knot cruise, 26-knot maximum. Strong private-use history highlighted. Large volume for its size. Higher asking price than the client's stated budget.</p><p><b>Yacht B</b></p><p>34.1m, 2016, <b>€7.29m asking</b>, 5 cabins, 10 guests, 266 GT, 10-knot cruise, 18-knot maximum. Private-use history highlighted. Recent refit and upgrades. Lower asking price.</p><p><b>Yacht C</b></p><p>34.64m, 2017, <b>€7.95m asking</b>, 5 cabins, 10 guests, 18-knot cruise, 25.5-knot maximum. Large aft beach-club area. Sky deck. Lateral tender garage. Approximately 1,620 engine hours listed.</p><p><b>Your brief</b></p><p>Your task is <b>not</b> to identify a universally \"best\" yacht. Your task is to demonstrate a professional process for helping Alex and Emma decide what deserves further attention. You will submit seven sections: client discovery, shortlist, investigation questions, broker recommendation, client pushback, the brief changes, and a broker self-check. The next pages take you through them one by one.</p>", "q": "What is the task in the Complete Broker Challenge?", "opts": ["To pick the cheapest yacht", "To sell Yacht A at asking price", "To demonstrate a professional process for deciding what deserves further attention, not to find a universally best yacht", "To invent the missing technical facts"], "correct": 2}, {"heading": "Challenge 1 and 2: Client Discovery and Shortlist", "body": "<p><b>1. Client discovery</b></p><p>Write the <b>five most important things you still need to discover</b> about Alex and Emma.</p><p><b>2. Shortlist</b></p><p>Assess all three yachts. For each, give client fit, lifestyle fit, main strength, main concern, important unknown, and why it deserves or does not deserve further attention. Then state: <b>\"My current shortlist is: ______.\"</b> Your shortlist may contain one, two or three yachts.</p>", "exercise": {"intro": "Work only from the information provided. Missing facts are unknowns.", "groups": [{"title": "1. Client discovery", "section": "yachts", "fields": [{"key": "cd_1", "label": "Discovery point 1: what do you still need to find out?", "type": "long", "min": 20}, {"key": "cd_2", "label": "Discovery point 2: what do you still need to find out?", "type": "long", "min": 20}, {"key": "cd_3", "label": "Discovery point 3: what do you still need to find out?", "type": "long", "min": 20}, {"key": "cd_4", "label": "Discovery point 4: what do you still need to find out?", "type": "long", "min": 20}, {"key": "cd_5", "label": "Discovery point 5: what do you still need to find out?", "type": "long", "min": 20}]}, {"title": "2. Shortlist: Yacht A", "section": "yachts", "fields": [{"key": "cs_a_fit", "label": "Yacht A: Client fit", "type": "long", "min": 15}, {"key": "cs_a_life", "label": "Yacht A: Lifestyle fit", "type": "long", "min": 15}, {"key": "cs_a_str", "label": "Yacht A: Main strength", "type": "long", "min": 15}, {"key": "cs_a_con", "label": "Yacht A: Main concern", "type": "long", "min": 15}, {"key": "cs_a_unk", "label": "Yacht A: Important unknown", "type": "long", "min": 15}, {"key": "cs_a_why", "label": "Yacht A: Why it does or does not deserve further attention", "type": "long", "min": 15}]}, {"title": "2. Shortlist: Yacht B", "section": "yachts", "fields": [{"key": "cs_b_fit", "label": "Yacht B: Client fit", "type": "long", "min": 15}, {"key": "cs_b_life", "label": "Yacht B: Lifestyle fit", "type": "long", "min": 15}, {"key": "cs_b_str", "label": "Yacht B: Main strength", "type": "long", "min": 15}, {"key": "cs_b_con", "label": "Yacht B: Main concern", "type": "long", "min": 15}, {"key": "cs_b_unk", "label": "Yacht B: Important unknown", "type": "long", "min": 15}, {"key": "cs_b_why", "label": "Yacht B: Why it does or does not deserve further attention", "type": "long", "min": 15}]}, {"title": "2. Shortlist: Yacht C", "section": "yachts", "fields": [{"key": "cs_c_fit", "label": "Yacht C: Client fit", "type": "long", "min": 15}, {"key": "cs_c_life", "label": "Yacht C: Lifestyle fit", "type": "long", "min": 15}, {"key": "cs_c_str", "label": "Yacht C: Main strength", "type": "long", "min": 15}, {"key": "cs_c_con", "label": "Yacht C: Main concern", "type": "long", "min": 15}, {"key": "cs_c_unk", "label": "Yacht C: Important unknown", "type": "long", "min": 15}, {"key": "cs_c_why", "label": "Yacht C: Why it does or does not deserve further attention", "type": "long", "min": 15}]}, {"title": "My shortlist", "section": "yachts", "fields": [{"key": "cs_list", "label": "My current shortlist is...", "type": "short", "min": 6}]}]}}, {"heading": "Challenge 3: Investigation Questions", "body": "<p><b>3. Investigation questions</b></p><p>Write <b>10 questions</b> you would investigate before making a serious recommendation, divided into four for the listing or broker side, three for technical specialists and three for Alex and Emma. Connect each question to a decision.</p>", "exercise": {"intro": "Every question should help make a decision.", "groups": [{"title": "Listing / broker side (4)", "section": "yachts", "fields": [{"key": "iq_l1", "label": "Listing/broker side, question 1", "type": "short", "min": 15}, {"key": "iq_l2", "label": "Listing/broker side, question 2", "type": "short", "min": 15}, {"key": "iq_l3", "label": "Listing/broker side, question 3", "type": "short", "min": 15}, {"key": "iq_l4", "label": "Listing/broker side, question 4", "type": "short", "min": 15}]}, {"title": "Technical specialists (3)", "section": "yachts", "fields": [{"key": "iq_t1", "label": "Technical specialists, question 1", "type": "short", "min": 15}, {"key": "iq_t2", "label": "Technical specialists, question 2", "type": "short", "min": 15}, {"key": "iq_t3", "label": "Technical specialists, question 3", "type": "short", "min": 15}]}, {"title": "Alex and Emma (3)", "section": "yachts", "fields": [{"key": "iq_c1", "label": "Alex and Emma, question 1", "type": "short", "min": 15}, {"key": "iq_c2", "label": "Alex and Emma, question 2", "type": "short", "min": 15}, {"key": "iq_c3", "label": "Alex and Emma, question 3", "type": "short", "min": 15}]}]}}, {"heading": "Challenge 4: Broker Recommendation", "body": "<p><b>4. Broker recommendation</b></p><p>Write approximately <b>250 words</b> to Alex and Emma. Include what you understand about their needs, which opportunity or opportunities you would prioritise, why, one important trade-off, one significant unknown and the next professional step.</p><p>Do not write <em>\"This is definitely the best yacht.\"</em> Use evidence-based language such as <em>\"Based on what you've told me...\"</em> or <em>\"I would prioritise this for further investigation because...\"</em></p>", "exercise": {"intro": "About 250 words, addressed to Alex and Emma.", "groups": [{"title": "My recommendation to Alex and Emma", "section": "services", "fields": [{"key": "br_text", "label": "Your recommendation (about 250 words)", "type": "long", "min": 800}]}]}}, {"heading": "Challenge 5 and 6: Pushback and the Brief Changes", "body": "<p><b>5. Client pushback</b></p><p>Alex says: <em>\"Why aren't you recommending the most expensive yacht? Surely €8.8m means it's the best one.\"</em> Write your response in <b>100 to 150 words.</b> Explain why <b>price is not quality, and quality is not suitability.</b></p><p><b>6. The brief changes</b></p><p>Emma says: <em>\"Actually, after thinking about it, we don't want to spend more than €7.5m.\"</em> Write a short <b>Revised Broker Assessment</b> of <b>150 to 200 words.</b> Cover what changes, what remains relevant, what questions become more important, whether the client brief needs to be revisited and what you would do next.</p>", "exercise": {"intro": "Explain value. Do not equate price with quality.", "groups": [{"title": "5. Client pushback", "section": "services", "fields": [{"key": "pb_text", "label": "Your response to Alex (100 to 150 words)", "type": "long", "min": 350}]}, {"title": "6. Revised broker assessment", "section": "services", "fields": [{"key": "rb_text", "label": "Your revised assessment (150 to 200 words)", "type": "long", "min": 500}]}]}}, {"heading": "Challenge 7: Broker Self-Check", "body": "<p><b>7. Broker self-check</b></p><p>Answer these six questions honestly, in one or two sentences each.</p>", "exercise": {"intro": "Honest, not flattering.", "groups": [{"title": "Self-check", "section": "profile", "fields": [{"key": "sc_1", "label": "1. Did I make assumptions that were not supported by the information?", "type": "long", "min": 20}, {"key": "sc_2", "label": "2. Did I separate facts from unknowns?", "type": "long", "min": 20}, {"key": "sc_3", "label": "3. Did I consider the client before the yacht?", "type": "long", "min": 20}, {"key": "sc_4", "label": "4. Did I identify meaningful trade-offs?", "type": "long", "min": 20}, {"key": "sc_5", "label": "5. Did I make a recommendation without pretending to have certainty?", "type": "long", "min": 20}, {"key": "sc_6", "label": "6. Did I explain what should happen next?", "type": "long", "min": 20}]}]}}, {"heading": "Model Answers and What Makes a Strong Submission", "body": "<p><b>Read these after completing the challenge</b></p><p>They are not intended to show that there is only one correct answer. A strong broker could reach a different conclusion and still demonstrate excellent judgment. The model demonstrates one reasonable way to structure the thinking.</p><p><b>Model 1: client discovery</b></p><p>&bull; <b>What does \"special\" actually mean?</b> Design, privacy, performance, entertaining, family experience, prestige or something else.<br/>&bull; <b>How important is keeping ownership simple?</b> This could significantly affect the type of yacht.<br/>&bull; <b>How will the children and guests actually use the yacht?</b> Guest numbers alone do not show how much separation, outdoor space or flexibility they need.<br/>&bull; <b>Where do they expect to cruise?</b> Mediterranean use is broad. The actual pattern may influence draft, range, marina access and operation.<br/>&bull; <b>Is €8m a firm ceiling or an approximate starting point?</b> This matters once Yacht A is considered at €8.8m.</p><p><b>Model 2: shortlist</b></p><p>&bull; <b>Yacht A:</b> potentially strong fit. Strength: large volume for its size and strong private-use positioning. Concern: €8.8m is above the approximate €8m budget. Unknown: technical condition, maintenance, operating costs and negotiation position. Keep under consideration, but clarify budget flexibility first.<br/>&bull; <b>Yacht B:</b> potentially strong fit. Strength: €7.29m leaves room within budget and the refit and upgrades may justify investigation. Concern: the scope and quality of the upgrades are not known. Strong candidate for further investigation.<br/>&bull; <b>Yacht C:</b> potentially strong fit, particularly for outdoor living. Strength: aft beach club, sky deck and tender garage. Concern: we do not know whether those features outweigh other compromises. Unknown: maintenance position, ownership history and operating complexity. Strong candidate.</p><p><b>Model shortlist: Yachts B and C,</b> but Yacht A should not be discarded immediately. If €8m is a hard ceiling, A becomes less relevant. The broker distinction: <b>do not eliminate an opportunity based on an assumption about the brief. Clarify the brief first.</b></p><p><b>Model 3: investigation questions</b></p><p>&bull; <b>Listing or broker side:</b> the complete ownership and usage history; exactly what the recent refit included; what major maintenance was completed and when; how long the yacht has been on the market and whether the asking price changed.<br/>&bull; <b>Technical specialists:</b> the condition of the main machinery and major systems; any known upcoming maintenance or replacement needs; any significant findings needing further investigation.<br/>&bull; <b>Alex and Emma:</b> is €8m a firm maximum; how important are outdoor entertaining and water sports compared with interior space; what does \"straightforward ownership\" mean to them in practice.</p><p><b>Model 4: recommendation</b></p><p><em>\"Based on what you've told me so far, I would initially prioritise Yachts B and C for further investigation. Both appear to sit closer to your stated budget, offer five guest cabins and could work well for the family-oriented Mediterranean use you've described. Yacht B is particularly interesting because its asking price leaves more room within the budget and the recent refit/upgrades may be valuable. I would want to understand exactly what was completed before placing too much weight on that point. Yacht C interests me for a different reason. The large aft beach-club area, sky deck and tender arrangement could be particularly well aligned with the relaxed outdoor lifestyle you described. Yacht A should remain in the conversation until we establish whether €8m is a firm ceiling. My next step would be to clarify your budget flexibility and investigate the maintenance, refit and operating position of B and C before arranging viewings.\"</em></p><p>The important feature is not the choice of B and C. It is the reasoning.</p><p><b>Model 5: client pushback</b></p><p><em>\"I wouldn't use price alone as a measure of which yacht is best for you. A higher asking price can reflect size, specification, condition, equipment or market positioning, but it doesn't automatically mean the yacht is the better fit for your family. The question is what you are actually buying for the additional money. If Yacht A provides something you value significantly more, the premium may be worth investigating. But if the lower-priced alternatives deliver the lifestyle you want without compromises that matter to you, spending more simply because the yacht costs more would not necessarily make sense.\"</em></p><p><b>Explain value; do not equate price with quality.</b></p><p><b>Model 6: the brief changes</b></p><p>The new €7.5m ceiling changes the search materially. Yacht A is now outside the budget and should generally leave the active shortlist unless the ceiling is reconsidered. Yacht B becomes particularly relevant at €7.29m. Yacht C at €7.95m is also above the ceiling, so establish whether €7.5m is genuinely firm. Revisit what \"special\" means: if outdoor family living and water sports matter most, C may justify asking whether the budget can move; if simplicity and budget discipline matter more, B becomes more relevant. Next step: confirm whether €7.5m is an absolute ceiling, then rebuild the shortlist around that constraint rather than removing yachts mechanically.</p><p><b>What makes a strong submission?</b></p><p>&bull; <b>Client first:</b> you start with what the client needs, not which yacht you like.<br/>&bull; <b>Evidence:</b> you distinguish information provided from assumptions.<br/>&bull; <b>Curiosity:</b> you identify the questions that matter.<br/>&bull; <b>Comparison:</b> you evaluate a yacht against alternatives.<br/>&bull; <b>Judgment:</b> you prioritise rather than hiding behind \"they're all good.\"<br/>&bull; <b>Balance and humility:</b> you explain strengths and weaknesses, and know what you do not know.<br/>&bull; <b>Communication and adaptability:</b> you explain clearly and change your recommendation when circumstances change.</p><p>A broker does not fall in love with their own recommendation. They stay loyal to the <b>client's needs.</b></p>", "q": "If a client's ceiling drops from €8m to €7.5m, what does the model answer say to do?", "opts": ["Confirm whether the new ceiling is firm, then rebuild the shortlist around the constraint rather than removing yachts mechanically", "Drop every yacht above the ceiling without asking", "Encourage the client to raise the ceiling", "Ignore the change until viewings"], "correct": 0}, {"heading": "Broker's Notebook: Module 7", "body": "<p><b>Broker's notebook</b></p><p>Complete these sentences.</p>", "exercise": {"intro": "Finish each sentence in your own words.", "groups": [{"title": "My notebook", "section": "profile", "fields": [{"key": "n7_1", "label": "I am beginning to notice that a good broker...", "type": "long", "min": 20}, {"key": "n7_2", "label": "The hardest part of making a recommendation is...", "type": "long", "min": 20}, {"key": "n7_3", "label": "I am most comfortable when...", "type": "long", "min": 20}, {"key": "n7_4", "label": "I need to become better at...", "type": "long", "min": 20}, {"key": "n7_5", "label": "One thing I would never want to do with a client is...", "type": "long", "min": 20}]}]}}, {"heading": "Professional Output: My First Broker Recommendation", "body": "<p><b>My First Broker Recommendation</b></p><p>Create a professional one-page recommendation. This is one of the most important pages in your Broker Portfolio so far.</p>", "exercise": {"intro": "Client, objective, shortlist, recommendation, why, trade-off, unknown, next step.", "groups": [{"title": "One-page recommendation", "section": "yachts", "fields": [{"key": "pr_client", "label": "CLIENT: who are they?", "type": "long", "min": 20}, {"key": "pr_obj", "label": "OBJECTIVE: what are they trying to achieve?", "type": "long", "min": 20}, {"key": "pr_short", "label": "SHORTLIST: which yachts deserve attention?", "type": "long", "min": 20}, {"key": "pr_rec", "label": "RECOMMENDATION: what would you prioritise?", "type": "long", "min": 30}, {"key": "pr_why", "label": "WHY: what evidence supports that view?", "type": "long", "min": 30}, {"key": "pr_trade", "label": "TRADE-OFF: what does the client need to understand?", "type": "long", "min": 30}, {"key": "pr_unk", "label": "UNKNOWN: what still needs verification?", "type": "long", "min": 30}, {"key": "pr_next", "label": "NEXT STEP: what should happen now?", "type": "long", "min": 20}]}]}}, {"heading": "Final Reflection and What Comes Next", "body": "<p><b>Module 7: final reflection</b></p><p>Stop for a moment. You have just done something different. You did not simply learn yacht terminology or memorise specifications. You were asked to understand a client, filter opportunities, compare yachts, identify uncertainty, ask questions, make a recommendation, explain your reasoning and respond when the brief changed. That is the beginning of broker thinking.</p><p>You may have found it enjoyable. You may have found it frustrating. You may have discovered that you naturally enjoy comparing options and solving client problems. Or you may have discovered that this part of brokerage does not appeal to you. Both are useful discoveries. There is no requirement to fall in love with the career. The purpose of this academy is to help you find out whether you could genuinely build a career in it.</p><p><b>What comes next</b></p><p><b>Module 8: Become the Broker.</b> <em>Can I communicate, sell and negotiate?</em> You can now think like a broker. Next, you have to sound like one. Excellent judgment has little commercial value if you cannot communicate it clearly. You will practise the first client conversation, better questions, presenting a yacht, handling objections, negotiating and professional communication. The next module is where your broker thinking becomes broker behaviour.</p>", "q": "What does Module 8 focus on?", "opts": ["Building yachts at the shipyard", "Communicating, presenting, handling objections and negotiating, turning broker thinking into broker behaviour", "Technical surveys of machinery", "Legal registration of yachts"], "correct": 1}]$json$;
  v_final jsonb := $json$[{"q": "What does it mean to \"think like a broker\"?", "opts": ["To memorise every yacht specification", "To recommend the yacht the broker personally likes", "To evaluate yachts in the context of the client, market, evidence, alternatives, risks and unknowns rather than simply describing or admiring the yacht", "To always favour the most expensive yacht"], "correct": 2}, {"q": "Why is a shortlist more useful than a long list?", "opts": ["The broker's role includes filtering information and directing the client's attention toward opportunities that genuinely deserve consideration", "Because clients dislike choice", "Because a long list is more expensive to send", "Because a shortlist removes the need for viewings"], "correct": 0}, {"q": "What makes a recommendation professional?", "opts": ["It states which yacht is definitely best", "It avoids naming any specific yacht", "It focuses on the yacht's headline specifications", "It connects to the client's needs, explains the reasoning, identifies trade-offs and uncertainties, and proposes a next step"], "correct": 3}, {"q": "Why should brokers distinguish facts from assumptions?", "opts": ["Because assumptions are always wrong", "Decisions should not be based on information that has not been verified", "Because facts are only found in listings", "Because clients do not want to hear assumptions"], "correct": 1}, {"q": "Does the most expensive yacht automatically provide the most value?", "opts": ["No. Price is only one factor; value depends on the client, yacht, condition, market position and operating reality", "Yes, price reflects quality", "Yes, if it is the newest yacht", "No, the cheapest yacht always provides most value"], "correct": 0}, {"q": "Why is the client's brief allowed to change?", "opts": ["Because brokers can override the brief", "Because the first brief is usually dishonest", "Clients often discover what matters to them through the process, and new information can change priorities, constraints and the search", "Because a fixed brief is never professional"], "correct": 2}, {"q": "What should a broker do when information is incomplete?", "opts": ["Fill the gaps with reasonable guesses", "Identify the uncertainty, ask the right questions, involve appropriate specialists and avoid presenting assumptions as facts", "Wait until the client asks", "Present the yacht as well documented"], "correct": 1}]$json$;
begin
  select id into v_module from public.academy_modules where track = 'yachts' and module_number = 7;
  if v_module is null then
    raise exception 'Yachts module 7 not found';
  end if;

  update public.academy_modules
     set title = 'Think Like a Broker', description = 'Can I actually do this?'
   where id = v_module;

  delete from public.academy_module_pages where module_id = v_module;
  delete from public.academy_quiz_questions where module_id = v_module;

  for rec in select * from jsonb_array_elements(v_pages) loop
    n := n + 1;
    if rec ? 'exercise' then
      insert into public.academy_module_pages (module_id, page_number, heading, body_html, checkpoint_question_id, exercise)
      values (v_module, n, rec->>'heading', rec->>'body', null, rec->'exercise');
    else
      insert into public.academy_quiz_questions (module_id, question_text, order_index, stage, page_number)
      values (v_module, rec->>'q', 0, 'checkpoint', n)
      returning id into v_q;

      for i in 0 .. jsonb_array_length(rec->'opts') - 1 loop
        insert into public.academy_quiz_options (question_id, option_text, is_correct, order_index)
        values (v_q, rec->'opts'->>i, i = (rec->>'correct')::int, i);
      end loop;

      insert into public.academy_module_pages (module_id, page_number, heading, body_html, checkpoint_question_id)
      values (v_module, n, rec->>'heading', rec->>'body', v_q);
    end if;
  end loop;

  n := 0;
  for rec in select * from jsonb_array_elements(v_final) loop
    n := n + 1;
    insert into public.academy_quiz_questions (module_id, question_text, order_index, stage)
    values (v_module, rec->>'q', n - 1, 'final')
    returning id into v_q;

    for i in 0 .. jsonb_array_length(rec->'opts') - 1 loop
      insert into public.academy_quiz_options (question_id, option_text, is_correct, order_index)
      values (v_q, rec->'opts'->>i, i = (rec->>'correct')::int, i);
    end loop;
  end loop;
end
$mig$;
